def _process_payload(result_queue, proc, tool):
    try: return result_queue.get(timeout=1)
    except queue.Empty:
        return dict(
            ok=False,
            error_type="ProcessError",
            error=f"{tool} process exited without a result payload; exit code {proc.exitcode}",
            stdout="",
            stderr="",
        )

