# %% ../nbs/07_mcp.ipynb #27561ec6
def _mcp_feedback_location(path, edit, default_cell_type="code"):
    edit_path = str(edit.get("path") or path)
    op = edit.get("op")
    if op == "replace_cell":
        cell_id = edit.get("cell_id")
        return edit_path, _mcp_cell_index(edit_path, cell_id), _mcp_structured_cell_count([edit], default_cell_type)
    if op == "replace_range":
        return edit_path, _mcp_cell_index(edit_path, edit.get("cell_id")), 1
    if op in {"insert_before", "insert_after"}:
        anchor_id = edit.get("anchor_id") or edit.get("cell_id")
        anchor_index = _mcp_cell_index(edit_path, anchor_id)
        start = anchor_index if op == "insert_before" else anchor_index + 1
        return edit_path, start, _mcp_structured_cell_count(edit.get("cells") or [edit], default_cell_type)
    return edit_path, None, 0

# %% ../nbs/07_mcp.ipynb #7c1eac0d
def _mcp_feedback_output(path, cell_ids, auto_feedback=True, feedback_timeout=10, feedback_safe=True, detail="summary", warnings=None):
    if not auto_feedback: return ""
    nb = _read_raw_nb(path)
    cells_by_id = {getattr(cell, "id", None): cell for cell in nb.cells}
    target_id = None
    for cell_id in cell_ids:
        cell = cells_by_id.get(cell_id)
        if cell is not None and should_run_cell_feedback(cell): target_id = cell_id
    if target_id is None: return ""
    try:
        output = _capture_exec_nb_process_call(dict(
            path=str(path), dest=None, exc_stop=False, up2id=target_id, chapter=None,
            timeout=feedback_timeout, show_output=True, verbose=False, safe=feedback_safe,
            allow=None, ok_dests=None, cache_httpx=False, cache_dir=None,
            cache_domains=None, allow_new=True, check_only=True,
        ), tool_timeout=feedback_timeout + 5)
    except (Exception, SystemExit) as exc:
        raw = str(exc).strip()
        first = next((line.strip() for line in raw.splitlines() if line.strip()), type(exc).__name__)
        first = " ".join(first.split())
        if len(first) > 160: first = first[:157].rstrip() + "..."
        failure = f"{type(exc).__name__}: {first}"
        message = f"Auto feedback failed (up to id={target_id}): auto_feedback_failed: {failure}"
        if warnings is not None:
            warnings.append({
                "code": "auto_feedback_failed",
                "message": f"auto_feedback_failed: {failure}",
                "next_action": "Run edit_notebook with detail='debug' to inspect full feedback output.",
                "path": str(path),
                "cell_id": target_id,
            })
        if detail == "debug" and raw:
            return f"{message}\n\nAuto feedback debug output:\n{raw}".rstrip()
        return message
    return f"Auto feedback (up to id={target_id}):\n{output}".rstrip()

# %% ../nbs/07_mcp.ipynb #56bbc791
def _mcp_smoke_preview(text, limit=1200):
    text = as_text(text).rstrip()
    if not text: return ""
    if len(text) <= limit: return text
    omitted = len(text) - limit
    return f"{text[:limit].rstrip()}\n... truncated {omitted} chars ..."


def _mcp_smoke_output_lines(label, text):
    preview = _mcp_smoke_preview(text)
    if not preview: return []
    lines = preview.splitlines()
    return [f"  {label}: {lines[0]}", *[f"  {line}" for line in lines[1:]]]


def _run_mcp_smoke_snippets(path, snippets, timeout=10):
    snippets = [str(snippet).strip() for snippet in (snippets or []) if str(snippet).strip()]
    if not snippets: return "", []
    cwd = git_root(path or ".") or _git_base(path or ".").resolve()
    lines, warnings = ["Smoke snippets:"], []
    for idx, snippet in enumerate(snippets, 1):
        try:
            proc = subprocess.run(
                [sys.executable, "-c", snippet], cwd=str(cwd), text=True,
                capture_output=True, timeout=timeout,
            )
        except subprocess.TimeoutExpired as exc:
            lines.append(f"- snippet {idx}: timeout after {timeout}s")
            lines.extend(_mcp_smoke_output_lines("stdout", exc.stdout))
            lines.extend(_mcp_smoke_output_lines("stderr", exc.stderr))
            warnings.append({
                "code": "smoke_snippet_timeout",
                "message": f"Smoke snippet {idx} timed out after {timeout}s.",
            })
            continue
        status = "ok" if proc.returncode == 0 else f"failed exit={proc.returncode}"
        lines.append(f"- snippet {idx}: {status}")
        lines.extend(_mcp_smoke_output_lines("stdout", proc.stdout))
        lines.extend(_mcp_smoke_output_lines("stderr", proc.stderr))
        if proc.returncode != 0:
            warnings.append({
                "code": "smoke_snippet_failed",
                "message": f"Smoke snippet {idx} failed with exit code {proc.returncode}.",
            })
    return "\n".join(lines), warnings


def _append_mcp_feedback(message, path, cell_ids, auto_feedback=True, feedback_timeout=10, feedback_safe=True, detail="summary", warnings=None):
    feedback = _mcp_feedback_output(path, cell_ids, auto_feedback, feedback_timeout, feedback_safe, detail, warnings)
    return "\n\n".join(chunk for chunk in [message.rstrip(), feedback] if chunk)

