def _mcp_call_id(tool):
    name = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(tool or "tool")).strip("-") or "tool"
    return f"{name}-{os.getpid()}-{time.monotonic_ns()}"

# %% ../nbs/07_mcp.ipynb #8813745f
def _mcp_log_event(event, **data):
    path = _mcp_log_path()
    if path is None: return
    payload = {
        "ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "pid": os.getpid(),
        "event": event,
    }
    payload.update({key: _mcp_json_safe(value) for key, value in data.items()})
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with _MCP_LOG_LOCK, path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, sort_keys=True) + "\n")
    except Exception:
        pass

