class _NbskillMCPLogMiddleware(Middleware):
    async def on_initialize(self, context, call_next):
        started = time.monotonic()
        _mcp_log_event("initialize_start", method=context.method)
        try: result = await call_next(context)
        except BaseException as exc:
            elapsed_ms = int((time.monotonic() - started) * 1000)
            _mcp_log_exception("initialize_error", exc, method=context.method, elapsed_ms=elapsed_ms)
            raise
        elapsed_ms = int((time.monotonic() - started) * 1000)
        _mcp_log_event("initialize_end", method=context.method, elapsed_ms=elapsed_ms)
        return result

    async def on_list_tools(self, context, call_next):
        started = time.monotonic()
        _mcp_log_event("tools_list_start", method=context.method)
        try: result = await call_next(context)
        except BaseException as exc:
            elapsed_ms = int((time.monotonic() - started) * 1000)
            _mcp_log_exception("tools_list_error", exc, method=context.method, elapsed_ms=elapsed_ms)
            raise
        elapsed_ms = int((time.monotonic() - started) * 1000)
        _mcp_log_event("tools_list_end", method=context.method, count=len(result or []), elapsed_ms=elapsed_ms)
        return result

    async def on_call_tool(self, context, call_next):
        tool = _mcp_middleware_tool_name(context)
        arguments = _mcp_middleware_tool_arguments(context)
        call_id = _mcp_call_id(tool)
        started = time.monotonic()
        _mcp_log_event("tool_start", tool=tool, call_id=call_id, arguments=arguments)
        try: result = await call_next(context)
        except BaseException as exc:
            elapsed_ms = int((time.monotonic() - started) * 1000)
            _mcp_log_exception(
                "tool_error", exc, tool=tool, call_id=call_id,
                arguments=arguments, elapsed_ms=elapsed_ms,
                result_status="transport_error",
            )
            raise
        elapsed_ms = int((time.monotonic() - started) * 1000)
        _mcp_log_event("tool_end", tool=tool, call_id=call_id, elapsed_ms=elapsed_ms, **_mcp_result_log_fields(result))
        return result

